insert into public.products (id,category_id,name,name_en,slug,description,description_en,sku,price,sale_price,images,stock_status,is_active,sort_order) values
('fa93bd53-6cde-45ee-b844-6bc685605635','026ad046-4886-46e2-a6c6-7271c3c897fc','ונטיק ארט - שועל - פסל מדף - ונטיק','Ventik Art - Fox - Shelf Sculpture - Ventik','vntyk-art-shval-psl-mdp-vntyk-5g87gm','<p>ונטיק ארט - שועל</p><p>מתוך סדרה של פסלי מתכת אמנותיים, עשויים בחיתוך לייזר, מבוססים על איורים של בעלי חיים מתוך ספר האיורים של המאיירת מלכה ונטיק זכרונה לברכה.</p><p>מלכה ונטיק נולדה באודסה ב – 1919 ועלתה ארצה ב-1923. היא התגוררה בשכונת יד אליהו בתל אביב ועבדה כמזכירה בבית יכין. במקביל לעבודתה היא למדה ציור בסטודיו הצבאי החופשי באלכסנדריה ובמכון אבני, בין היתר אצל יצחק פרנקל,&nbsp;מוקדי, ינקו, סטימצקי, שטרייכמן חנה טברסקי ועוד. ב - 1967 יצא בהוצאת ברונפמן ספר האיורים שלה: ''''רישומים - דמויות בעלי חיים'''' הספר כולל 24 איורים של בעלי חיים אותם ראתה ורשמה בווירטואוזיות בגן החיות בת"א (איפה שהיום ממוקם גן העיר).</p><p>מלכה ונטיק היתה אחות של סבא שלי. לה לא היו ילדים משלה ולי לא היו סבא וסבתא אחרים, כך שלמעשה היא הייתה הסבתא שלי.</p><p>לרגל 50 שנה לפרסומו של הספר שלה, בחרתי מספר רישומים מתוכו והפכתי אותם לפסלים ממתכת בחיתוך לייזר, תוך שאני מנסה לשמר כמה שיותר את הקו העדין והנקי של האיורים.</p><p>הפסלים מגיעים בגרסה של פסל קטן למדף ושני גדלים גדולים יותר לתליה על קיר. הם מפיחים חיים באיורים היפים שכמעט ונשכחו והופכים אותם לאלמנט עכשווי, אסתטי ומיוחד.</p><p>מקווה שתאהבו,</p><p>אורי ניב – מייסד ובעלים של המותג ארטאורי דיזיין</p>','<p>Ventik Art - Fox</p><p>From a series of artistic metal sculptures, made with laser cutting, based on animal illustrations from the illustration book by illustrator Malka Ventik of blessed memory.</p><p>Malka Ventik was born in Odessa in 1919 and immigrated to Israel in 1923. She lived in the Yad Eliyahu neighborhood in Tel Aviv and worked as a secretary at Beit Yachin. Alongside her work, she studied painting at the Free Military Studio in Alexandria and at the Avni Institute, among others with Yitzhak Frenkel, Mokady, Yanko, Stematsky, Streichman, Hanna Taversky and more. In 1967, Bronfman Publishing released her illustration book: ''Drawings - Animal Figures''. The book includes 24 illustrations of animals that she saw and sketched with virtuosity at the Tel Aviv Zoo (where the City Garden is located today).</p><p>Malka Ventik was my grandfather''s sister. She had no children of her own and I had no other grandparents, so she was essentially my grandmother.</p><p>To mark 50 years since the publication of her book, I selected several drawings from it and turned them into laser-cut metal sculptures, while trying to preserve as much as possible the delicate and clean line of the illustrations.</p><p>The sculptures come in a small shelf sculpture version and two larger sizes for wall hanging. They breathe life into the beautiful illustrations that were almost forgotten and turn them into a contemporary, aesthetic and special element.</p><p>I hope you''ll love them,</p><p>Uri Niv - Founder and owner of the Artauri Design brand</p>',NULL,0.00,NULL,ARRAY['assets/product-1773749759000-zuxbgp.webp','assets/product-1773749760276-zj1y2b.webp','assets/product-1773749761345-70ew2m.webp','assets/product-1773749761873-79gfyp.webp','assets/product-1773749762876-pzilfh.webp','assets/product-1773749763772-ozot5.webp']::text[],'in_stock',true,0),
('ae42b73f-743c-4249-9a56-b72c9854d6ce','ce5466ef-0dfb-4e8d-81f3-84791574cf8c','הנסיכה במגדל - מעמד מעוצב לנייר מגבת','The Princess in the Tower - Decorative Paper Towel Holder','hnsykh-bmgdl-mamd-mavtsb-lnyyr-mgbt-burfax','<p class="ql-align-right">הנסיכה במגדל הוא מתקן קסום לנייר סופג הלוכד סצינה מפורסמת מהאגדות של הנסיכה הכלואה במגדל והנסיך המגיע להציל אותה.</p><p class="ql-align-right">זוהי מתנה יפיפיה מהאגדות, מתאימה לאבירים ולנסיכות. מוצר עיצובי ופונקציונלי לשדרוג המטבח.</p><p>בסיס המוצר מרופד ב- eva למניעת שריטות או נוזלים.</p>','<p class="ql-align-right">The Princess in the Tower is a magical paper towel holder that captures a famous fairy tale scene of a princess locked in a tower and the prince arriving to rescue her.</p><p class="ql-align-right">This is a beautiful, fairy tale-inspired gift, perfect for knights and princesses alike. A decorative and functional product to upgrade your kitchen.</p><p>The base of the product is lined with EVA to prevent scratches or liquid damage.</p>','AD195',159.90,NULL,ARRAY['assets/product-1773749759034-jjcrp9.webp','assets/product-1773749759835-gulfu6.webp','assets/product-1773749760679-ami14.webp','assets/product-1773749761442-zg2bzx.webp','assets/product-1773749762363-i1b8jb.webp']::text[],'out_of_stock',true,0),
('3b7ecd3e-19fc-4890-b77d-b179c3e319b6','125da808-02d5-4a87-84f2-a261898d446d','סיזיפוס - מדף מעוצב נטוי, לאחסון גלילי נייר טואלט - שחור/אפור','Sisyphus - Designed Tilted Shelf for Toilet Paper Roll Storage - Black/Gray','syzypvs-mdp-mavtsb-ntvy-lachsvn-glyly-nyyr-tvalt-shchvrapvr-ttzuc6','<p><strong>סיזיפוס - מדף מעוצב לתליה בחדר השירותים / האמבטיה</strong> מדף אלכסוני לאחסון גלילי נייר טואלט, המעניק משמעות חדשה למושג &quot;עבודה סיזיפית&quot;.</p><p>סיזיפוס, הדמות הטראגית מהמיתולוגיה היוונית שנגזר עליו לגלגל סלע ענק עד לפסגת ההר רק כדי לראות אותו מתגלגל חזרה מטה שוב ושוב, מתגייס הפעם כדי להחזיק את גלילי נייר הטואלט שלכם במעלה המדרון ללא לאות. המדף יכול להכיל 6-10 גלילי נייר טואלט, תלוי בקוטרם, במגוון העמדות.</p><p>מתנה הומוריסטית לעיצוב חדר השירותים והאמבטיה.</p><p></p><p>הוראות:</p><p>-         חברו את דמות סיזיפוס למדף באמצעות הבורג והאום המצורפים.</p><p>-         בחרו מקום על קיר בעל פני שטח חלקים (כגון קיר עץ, גבס או אריחים).</p><p>-     מקמו את המדף לקיר בזוית של 7 עד 30 מעלות, לשימוש נכון והמראה הרצוי.</p><p>-         השתמשו בברגים המצורפים לערכה לתלייה מאובטחת ויציבה</p><p>בצבעים שחור ואפור</p>','<p><strong>Sisyphus - Designed Hanging Shelf for the Bathroom / Toilet</strong> A diagonal shelf for storing toilet paper rolls, giving new meaning to the concept of &quot;Sisyphean work&quot;.</p><p>Sisyphus, the tragic figure from Greek mythology condemned to roll a giant boulder up to the top of a hill only to watch it roll back down again and again, is now enlisted to hold your toilet paper rolls up the slope tirelessly. The shelf can hold 6-10 toilet paper rolls, depending on their diameter, in a variety of positions.</p><p>A humorous gift for bathroom and toilet décor.</p><p></p><p>Instructions:</p><p>-         Attach the Sisyphus figure to the shelf using the included screw and nut.</p><p>-         Choose a spot on a wall with a smooth surface (such as a wood, drywall, or tiled wall).</p><p>-     Position the shelf against the wall at an angle of 7 to 30 degrees for proper use and the desired look.</p><p>-         Use the screws included in the kit for a secure and stable mount</p><p>Available in black and gray</p>','AD198_9',139.00,NULL,ARRAY['assets/product-1773749741733-udqcvc.webp','assets/product-1773749742790-m8i6q.webp','assets/product-1773749744064-qo5nl.webp','assets/product-1773749744441-7tbpap.webp','assets/product-1773749745165-4tzuak.webp','assets/product-1773749745834-kbpsu5.webp','assets/product-1773749746447-y6rjgr.webp','assets/product-1773749747533-oeccv.webp','assets/product-1773749748401-r37x8.webp','assets/product-1773749749309-vlyajs.webp','assets/product-1773749750095-vll7kp.webp','assets/product-1773749750609-x997pv.webp','assets/product-1773749751013-zzr1j.webp','assets/product-1773749751622-1n5t6.webp','assets/product-1773749752140-ijhwxn.webp','assets/product-1773749752770-l2vdl.webp','assets/product-1773749753670-wxsg7.webp','assets/product-1773749754325-to2ixn.webp','assets/product-1773749755085-sp8so.webp','assets/product-1773749755551-uowhb6.webp','assets/product-1773749756245-jup62b.webp','assets/product-1773749756954-1z0y8rf.webp','assets/product-1776335499293-thisd5.webp']::text[],'in_stock',true,0),
('fe6b0eb1-9793-4585-b16b-7c77830d71c4','2420ab78-5daa-4119-8e1d-b986d78ab658','דיוה ופרינסס - זוג פסלוני חתולים למדף','Diva and Princess - Pair of Cat Figurines for Shelf','dyvh-vprynss-zvg-pslvny-chtvlym-lmdp-5n1007','<p class="ql-align-right">זוג פסלוני חתולים, מתוך סדרה של 5 חתולים מקסימים שיושבים על קצה מדף, לקישוט מדפים, נישות וכו''.</p><p class="ql-align-right">הזוג במחיר מוזל!</p><p class="ql-align-right">קיימים 3 דגמי זוגות לבחירה: דיווה ופרינסס, דיווה וצ''רצ''יל, פרינסס ושרלוק</p><p class="ql-align-right">קיימים חמישה דגמים בודדים לבחירה: דיווה, צ''רצ''יל, אוסקר, שרלוק, פרינסס.</p>','<p class="ql-align-right">A pair of cat figurines, from a series of 5 adorable cats that sit on the edge of a shelf, for decorating shelves, niches, etc.</p><p class="ql-align-right">The pair at a discounted price!</p><p class="ql-align-right">Available in 3 pair models to choose from: Diva and Princess, Diva and Churchill, Princess and Sherlock</p><p class="ql-align-right">Available in five individual models to choose from: Diva, Churchill, Oscar, Sherlock, Princess.</p>','AD192DP',95.00,NULL,ARRAY['assets/product-1773749741835-bthpu.webp','assets/product-1773749743184-3xlz6c.webp','assets/product-1773749743684-3btybk.webp','assets/product-1773749703567-okasji.webp','assets/product-1773749744369-bjzshs.webp']::text[],'in_stock',true,0),
('3847e7f0-132e-4763-8b40-0cc3664390a7','72300d79-90b2-4d50-bbec-1246766a6c62','בלקוני - מדף מפתחות דקורטיבי - דגם A Hers','Balcony - Decorative Key Shelf - Model A Hers','blkvny-mdp-mptchvt-dkvrtyby-dgm-a-hers-n8l516','<p>איפה אתם מרוקנים את הכיסים כשאתם נכנסים הביתה? הכירו את בלקוני – מדף מפתחות ושאר ירקות לכניסה לבית. מרפסת פסטורלית שמסמלת עבורכם את זמן הרגיעה של סוף היום&nbsp;וגם מרכזת במקום אחד את כל הבלגן של מפתחות, טלפון נייד, משקפיים, כסף קטן, ככה שתמצאו אותם בקלות לפני היציאה מהבית. בלקוני הוא פריט פונקציונלי ועיצובי לחלל המגורים שלכם.</p><p>ארבעה דגמים עשויים מתכת בציפוי וגימור איכותי, מסופקים עם משטח שעם נעים לריפוד רצפת המרפסת, עם שני ברגים לתליה קלה ועם מגנט קטן להצמדת פתקים.</p>','<p>Where do you empty your pockets when you come home? Meet Balcony – a key shelf and other essentials for your home entrance. A pastoral balcony that symbolizes your end-of-day relaxation time and also centralizes all the clutter of keys, mobile phone, glasses, small change in one place, so you can easily find them before leaving the house. Balcony is a functional and design item for your living space.</p><p>Four models made of metal with quality coating and finish, supplied with a pleasant surface for cushioning the balcony floor, with two screws for easy hanging and with a small magnet for attaching notes.</p>','AD124',169.00,NULL,ARRAY['assets/product-1773749741556-g1kt2l.webp','assets/product-1773749743184-341b38.webp','assets/product-1773749744361-jr4g6d.webp','assets/product-1773749745166-vd307f.webp','assets/product-1773749746238-t4y43.webp','assets/product-1773749747381-irzinfi.webp','assets/product-1773749747997-qqckz.webp','assets/product-1773749748432-2fuvmb4.webp','assets/product-1773749749091-eznr0p.webp','assets/product-1773749749947-wqqrw.webp']::text[],'in_stock',true,0),
('016e001a-09f7-4c8d-8574-fe207d984624','f26acbb7-bd54-436a-9c23-f333551ead1b','וולי - סימנית אטב לספר, מעוצבת כתולעת ספרים','Wally - Bookworm Clip-On Bookmark, Designed as a Book Worm','vvly-symnyt-atb-lspr-mavtsbt-ktvlat-sprym-emh7kb','<p>וולי</p><p>סימניה מדליקה לאוהבי הקריאה והספרים.</p><p>מתנה מושלמת לכל תולעת ספרים.</p><p>הסימניה מעוצבת כקליפ (אטב) בצורת תולעת ספרים שמתפתלת סביב פינת הספר, פנימה והחוצה.</p>','<p>Wally</p><p>A fun bookmark for reading and book lovers.</p><p>The perfect gift for every bookworm.</p><p>The bookmark is designed as a clip in the shape of a bookworm that winds around the corner of the book, in and out.</p>','AD38..',29.00,NULL,ARRAY['assets/product-1773749741571-jhnji.webp','assets/product-1773749742398-w9o2xk.webp','assets/product-1773749743649-ic9k8m.webp','assets/product-1773749744179-tuoq3.webp','assets/product-1773749744781-53ujeu.webp','assets/product-1773749745971-y0mhj8.webp','assets/product-1773749746789-gk03yk.webp','assets/product-1773749747277-z96x3w.webp','assets/product-1773749747748-n4sfd7.webp','assets/product-1773749748290-jivnd.webp']::text[],'in_stock',true,0),
('f8012143-bb8f-457c-8d19-338d42bae026','2420ab78-5daa-4119-8e1d-b986d78ab658','פרינסס ושרלוק - זוג פסלוני חתולים למדף','Princess and Sherlock - Pair of Cat Figurines for Shelf','prynss-vshrlvk-zvg-pslvny-chtvlym-lmdp-nnx9cv','<p class="ql-align-right">זוג פסלוני מתכת של חתולים, מתוך סדרה של 5 חתולים מקסימים, שיושבים על קצה מדף. לקישוט מדפים, נישות וכו''.</p><p class="ql-align-right">הזוג במחיר מוזל!</p><p class="ql-align-right">קיימים 3 דגמי זוגות לבחירה: דיווה ופרינסס, דיווה וצ''רצ''יל, פרינסס ושרלוק</p><p class="ql-align-right">קיימים חמישה דגמים בודדים לבחירה: דיווה, צ''רצ''יל, אוסקר, שרלוק, פרינסס.</p>','<p class="ql-align-right">A pair of metal cat figurines from a series of 5 adorable cats that sit on the edge of a shelf. For decorating shelves, niches, etc.</p><p class="ql-align-right">The pair at a discounted price!</p><p class="ql-align-right">Available in 3 pair models to choose from: Diva and Princess, Diva and Churchill, Princess and Sherlock</p><p class="ql-align-right">Available in five individual models to choose from: Diva, Churchill, Oscar, Sherlock, Princess.</p>','AD192PS',95.00,NULL,ARRAY['assets/product-1773749741731-4qq1vh.webp','assets/product-1773749742789-qduxk.webp','assets/product-1773749743477-fcten.webp','assets/product-1773749744282-1m7f2s.webp','assets/product-1773749745559-984kw.webp','assets/product-1773749746843-w1gmjf.webp']::text[],'in_stock',true,0),
('e33f63f3-7e8d-462b-adf2-58ab9842063a','2420ab78-5daa-4119-8e1d-b986d78ab658','דיוה וצ׳רצ׳יל - זוג פסלוני חתולים לקישוט מדף','Diva and Churchill - Pair of Cat Figurines for Shelf Decoration','dyvh-vtsrtsyl-zvg-pslvny-chtvlym-lkyshvt-mdp-5qm69a','<p class="ql-align-right">זוג חתולים, מתוך סדרה של 5 חתולים מקסימים שיושבים על קצה מדף, לקישוט מדפים, נישות וכו''.</p><p class="ql-align-right">הזוג במחיר מוזל!</p><p class="ql-align-right">קיימים 3 דגמי זוגות לבחירה: דיווה ופרינסס, דיווה וצ''רצ''יל, פרינסס ושרלוק</p><p class="ql-align-right">קיימים חמישה דגמים בודדים לבחירה: דיווה, צ''רצ''יל, אוסקר, שרלוק, פרינסס.</p>','<p class="ql-align-right">A pair of cats from a series of 5 adorable cats that sit on the edge of a shelf, for decorating shelves, niches, etc.</p><p class="ql-align-right">The pair at a discounted price!</p><p class="ql-align-right">Available in 3 pair models to choose from: Diva and Princess, Diva and Churchill, Princess and Sherlock</p><p class="ql-align-right">Available in five individual models to choose from: Diva, Churchill, Oscar, Sherlock, Princess.</p>','AD192CD',95.00,NULL,ARRAY['assets/product-1773749741835-inq15.webp','assets/product-1773749699544-8tdzce.webp','assets/product-1773749742788-m4mp4.webp','assets/product-1773749743643-io2sv9.webp','assets/product-1773749744661-1smmc.webp']::text[],'in_stock',true,0),
('4d2d5d79-ff5e-4f47-aa6c-0a787675cf8a','c4d77b37-fc91-4e2c-9a25-5419c13bdbc3','תחתיות לכוסות מעוצבות כשטיחוני רכב','Designer Car Mat Style Coasters','tchtyvt-lkvsvt-mavtsbvt-kshtychvny-rkb-v9xase','<p class="ql-align-right">סט של 4 תחתיות לכוסות (קוסטרים) מעוצבות כשטיחוני רכב. התחתיות עשויות סיליקון איכותי, מונע החלקה, אוגר בתוכו את הנוזלים, ניתן לניקוי ושטיפה במדיח כלים ומחזיק מעמד לאורך זמן. זוהי מתנה מקורית ושימושית מאוד, לגברים ונשים כאחד, חובבי רכב ואוהבי גאדג''טים. למי שדואג ושומר על הניקיון על הרכב וגם על הבית...</p>','<p class="ql-align-right">Set of 4 coasters designed as car mats. The coasters are made of high-quality silicone, prevent slipping, absorb liquids, are dishwasher safe and durable over time. This is a very original and useful gift for both men and women, car enthusiasts and gadget lovers. For those who care about and maintain cleanliness in both their car and home...</p>','AD348',55.00,NULL,ARRAY['assets/product-1773749725270-wqls89.webp','assets/product-1773749726158-2vle7b.webp','assets/product-1773749727059-hdvem.webp','assets/product-1773749727757-vafn8w.webp','assets/product-1773749728189-or21pl.webp','assets/product-1773749730094-r3tnqt.webp','assets/product-1773749730586-l0dkjb.webp','assets/product-1773749738863-ijcdd.webp','assets/product-1773749739565-2g2lmm.webp','assets/product-1773749740210-notz4u.webp']::text[],'in_stock',true,0),
('3c7c8187-6441-42a9-ac5d-f9f51639c5b1','80589292-7ecc-49ab-b2f1-31e1458cd6fd','מחזיק מעמד - קישוט למדף','Steadfast Holder - Shelf Decoration','mchzyk-mamd-kyshvt-lmdp-lghfsg','<p class="ql-align-right">ה"מחזיק מעמד" הוא סוג של גיבור על שנותן את התחושה שהוא מונע מחפצים שונים מליפול. ה"מחזיק מעמד" עובד בצורה אידיאלית כאשר מצמידים אותו לחפצים שאופן החיבור שלהם אינו גלוי לעין. לדוגמא "מחזיק מעמד" מתאים מאוד למדף צף כגון זה של איקיאה. המגנט בידה של הדמות, מתמגנט לבורג הנסתר המצוי בתחתית המדף כך שנוצר הרושם שהוא זה שמחזיק אותו מליפול. ניתן להשתמש במוצר בחפצים נוספים כגון שעונים, מסגרות תמונה וכו''. ה"מחזיק מעמד" הוא תוספת קולית לקישוט הבית, היא יוצרת עניין ומעלה חיוך. לא רק למעריצי גיבורי על.</p>','<p class="ql-align-right">The "Steadfast Holder" is a type of superhero that gives the feeling that he prevents various objects from falling. The "Steadfast Holder" works ideally when attached to objects where their connection method is not visible to the eye. For example, the "Steadfast Holder" is very suitable for a floating shelf such as IKEA''s. The magnet in the character''s hand magnetizes to the hidden screw located at the bottom of the shelf, creating the impression that he is the one holding it from falling. The product can be used with additional objects such as clocks, picture frames, etc. The "Steadfast Holder" is a vocal addition to home decoration, it creates interest and brings a smile. Not just for superhero fans.</p>','AD108',69.00,NULL,ARRAY['assets/product-1773749725065-3mftho.webp','assets/product-1773749725733-j3zd9.webp','assets/product-1773749726270-jnquen.webp','assets/product-1773749727877-ctundm.webp','assets/product-1773749731353-nkoe5a.webp','assets/product-1773749731761-rw136r.webp']::text[],'in_stock',true,0),
('b98f8d02-0384-475b-aaff-2e813b67d4e8','d448b992-d73d-4f0b-a46b-27ae8952220f','מסגרת גומיות - מתקן שולחני לפתקי ממו ותמונות','Rubber Band Frame - Desktop Stand for Memo Notes and Photos','msgrt-gvmyvt-mtkn-shvlchny-lptky-mmv-vtmvnvt-hi2bwe','<p>מסגרת דקורטיבית לתליית תמונות, פתקים, חשבונות, כרטיסי ביקור וכו''.</p><p>&nbsp;המסגרת עשויה מברזל בצביעה איכותית בתנור וכוללת בתוכה אלמנטים קישוטיים המשמשים כעוגנים למתיחת&nbsp;גומיות מצד אחד לשני עד כדי יצירת מעין רשת, שעליה ניתן לתלות דברים שונים.</p><p>המסגרת ניתנת לתלייה על הקיר וגם להצבה על שולחן או מדף באמצעות רגלית שמסופקת עם המוצר (בשני המקרים השימוש אפשרי לאורך או לרוחב).</p><p>המסגרת מסופקת עם מספר גומיות כך שניתן להשתמש בה באופן מידי. עם זאת, ניתן ואף רצוי להשתמש במסגרת לשימוש חוזר בגומיות שונות שיש תמיד בבית או במשרד.</p><p>שילובים שונים ויצירתיים של הגומיות על המסגרת, יוצרת מוצר משתנה ודינמי ומאפשרת להביא לידי ביטוי את היצירתיות של המשתמש.</p><p>זו מתנה דקורטיבית ושימושית כאחד, לבית או לסביבת העבודה, עוזרת בארגון וסדר, כיפית ויצירתית לשימוש ויפה לעין.</p><p>זמין בשני גדלים:</p><p>גדול 35X25</p><p>קטן 24X17.5</p>','<p>Decorative frame for hanging photos, notes, bills, business cards, etc.</p><p>&nbsp;The frame is made of iron with high-quality oven-baked paint and includes decorative elements that serve as anchors for stretching&nbsp;rubber bands from one side to the other to create a kind of net, on which various items can be hung.</p><p>The frame can be hung on the wall or placed on a desk or shelf using the stand that comes with the product (in both cases it can be used horizontally or vertically).</p><p>The frame comes with several rubber bands so it can be used immediately. However, it''s possible and even recommended to reuse different rubber bands that are always available at home or in the office.</p><p>Various and creative combinations of rubber bands on the frame create a changing and dynamic product and allow users to express their creativity.</p><p>This is both a decorative and practical gift for home or work environment, helps with organization and order, fun and creative to use and beautiful to look at.</p><p>Available in two sizes:</p><p>Large 35X25</p><p>Small 24X17.5</p>','AD236P',69.00,49.00,ARRAY['assets/product-1773749724648-axbqlr.webp','assets/product-1773749725181-cica1l.webp','assets/product-1773749725955-awwkcm.webp','assets/product-1773749727038-ef924c.webp','assets/product-1773749727748-fr3haf.webp','assets/product-1773749728236-7mewuo.webp','assets/product-1773749728790-cq1zp.webp','assets/product-1773749729315-dtzw3f.webp','assets/product-1773749729810-936kec.webp','assets/product-1773749730272-lppfsu.webp','assets/product-1773749730907-5quao8.webp']::text[],'in_stock',true,0),
('0bb3d490-82bd-4835-8b6f-40b34f9d6775','99308e90-f80c-4e23-9611-1b61f0e2c0a5','בטיפול שלה - כיסוי לקופסת טישו מלבנית','In Her Treatment - Rectangular Tissue Box Cover','btypvl-shlh-kysvy-lkvpst-tyshv-mlbnyt-3zw8g4','<p>בטיפול שלה - In her Treatment</p><p class="ql-align-right">קישוט/כיסוי מדליק ומעוצב לקופסת טישו מלבנית בגודל סטנדרטי. הכיסוי מונח על הקופסא ומתאר בצלליות סיטואציה של טיפול פסיכולוגי, כאשר בין הפסיכולוגית לפציינטית - ממחטת נייר לעת הצורך... המוצר משדרג כל קופסת טישו עשויה קרטון המונחת בבית או במשרד (או בקליניקה של הפסיכולוגית), וגורר תגובות וחיוכים.</p><p class="ql-align-right"><br></p><p>זו מתנה עם הומור, למטפלות, מטופלות או סתם מצוננות..</p><p>עשוי מתכת, נמכר באריזת מתנה יוקרתית עם קופסת טישו בצבע לבן חלק שניתן להחליף בכל קופסת טישו מלבנית סטנדרטית אחרת.</p><p>קופסת הטישו הפרחונית שבתמונה - להמחשה בלבד.</p><p class="ql-align-right">מידות: גובה: 19 ס"מ, אורך: 11 ס"מ, עומק: 9 ס"מ . משקל: 220 גר''.</p>','<p>In Her Treatment - בטיפול שלה</p><p class="ql-align-right">A stunning and stylish decoration/cover for a standard-sized rectangular tissue box. The cover sits on the box and depicts in silhouettes a psychological treatment situation, where between the psychologist and the patient - a tissue dispenser for when needed... The product upgrades any cardboard tissue box placed at home or in the office (or in the psychologist''s clinic), and draws reactions and smiles.</p><p class="ql-align-right"><br></p><p>This is a gift with humor, for therapists, patients, or just people with colds..</p><p>Made of metal, sold in a luxurious gift box with a plain white tissue box that can be replaced with any other standard rectangular tissue box.</p><p>The floral tissue box in the image - for illustration only.</p><p class="ql-align-right">Dimensions: Height: 19 cm, Length: 11 cm, Depth: 9 cm. Weight: 220 gr.</p>','AD193',109.00,NULL,ARRAY['assets/product-1773749724256-7u136y.webp','assets/product-1773749724593-snpqx.webp','assets/product-1773749725141-5gqvs6.webp','assets/product-1773749725573-qytl8l.webp','assets/product-1773749726564-k9rxs.webp','assets/product-1773749727444-uvqwd.webp','assets/product-1773749728032-9jokhc.webp','assets/product-1773749728471-k8acso.webp','assets/product-1773749729136-7zuyn9.webp','assets/product-1773749729541-597upv.webp','assets/product-1773749730018-iiifdo.webp']::text[],'in_stock',true,0),
('5dff4359-20b0-4969-bc10-80cacb70eddf','99308e90-f80c-4e23-9611-1b61f0e2c0a5','בטיפול שלה - כיסוי לקופסת טישו מרובעת','In Her Care - Square Tissue Box Cover','btypvl-shlh-kysvy-lkvpst-tyshv-mrvbat-19e261','<p class="ql-align-right">כיסוי לקופסת טישו מרובעת בגודל סטנדרטי.</p><p class="ql-align-right">הגרסה הנשית ל"בטיפול" הפעם מתארת סצינה של פסיכולוגית ומטופלת.</p><p class="ql-align-right">הכיסוי מונח על הקופסא ומתאר בצלליות סיטואציה של טיפול פסיכולוגי, כאשר בין הפסיכולוגית לפציאנטית, ממחטת נייר לעת הצורך... המוצר משתלב ומשדרג כל קופסת טישו מרובעת עשויה קרטון המונחת בבית או במשרד (או בקליניקה של הפסיכולוגית). מתנה עם הומור למטפלות, מטופלות או סתם מצוננות..</p><p class="ql-align-right">צבע: שחור</p><p class="ql-align-right">לא כולל קופסת טישו.</p><p class="ql-align-right">חומר : מתכת</p><p class="ql-align-right">מיוצר בישראל</p><p class="ql-align-right">מימדים:</p><p class="ql-align-right">גובה - 5 ס"מ, אורך11 ס"מ, רוחב 11 ס"מ.</p><p class="ql-align-right">משקל : 140 גרם.</p>','<p class="ql-align-right">Square tissue box cover in standard size.</p><p class="ql-align-right">The feminine version of "In Care" this time depicts a scene of a psychologist and patient.</p><p class="ql-align-right">The cover sits on the box and depicts in silhouettes a psychological therapy situation, where between the psychologist and patient, tissues are available when needed... The product integrates with and upgrades any square cardboard tissue box placed at home or in the office (or in the psychologist''s clinic). A humorous gift for therapists, patients, or just people with colds..</p><p class="ql-align-right">Color: Black</p><p class="ql-align-right">Does not include tissue box.</p><p class="ql-align-right">Material: Metal</p><p class="ql-align-right">Made in Israel</p><p class="ql-align-right">Dimensions:</p><p class="ql-align-right">Height - 5 cm, Length 11 cm, Width 11 cm.</p><p class="ql-align-right">Weight: 140 grams.</p>','AD194',55.00,NULL,ARRAY['assets/product-1773749724859-jm9vfm.webp','assets/product-1773749725433-etmnff.webp','assets/product-1773749725955-50ycxb.webp','assets/product-1773749726564-qj2l9.webp','assets/product-1773749727435-40ecz9.webp']::text[],'out_of_stock',true,0),
('81586164-c917-406f-a097-6bcb22db14ac','f646f62d-2bf6-4721-9020-141031e08ece','קולב קוביות תלת מימד - 6 קוביות','3D Cubes Hanger - 6 Cubes','kvlb-kvbyvt-tlt-mymd-6-kvbyvt-qnuvi1','<p class="ql-align-right">מתלה בצורת קוביות תלת מימדיות המשמש לאחסון מטפחות, עניבות, צעיפים, חגורות, תכשיטים ועוד. המתלה נותן תחושה שהוא תלת מימדי בעוד הוא שטוח לגמרי, חוסך מקום ונוח לאחסון ותליה. קיים בשני דגמים, 6 קוביות הכולל 11 פתחים המשמשים לאחסון ושלוש קוביות הכולל 5 פתחים המשמשים לתליה. מוצר זה הוא 6 קוביות. זו מתנה דקורטיבית ומעוצבת ומאוד שימושית לבית, עוזרת בארגון וסדר ויפה לעין. מידות: גובה 24ס"מ, רוחב 22.7ס"מ עובי&nbsp;2&nbsp;מ"מ. צבע: שחור. משקל: 300&nbsp;גרם. חומר: ברזל בצביעה בתנור.</p><p class="ql-align-right"><br></p><p>נמכר באריזת צלופן איכותית, שטוחה וחוסכת מקום.</p>','<p class="ql-align-right">A hanger in the shape of three-dimensional cubes used for storing handkerchiefs, ties, scarves, belts, jewelry and more. The hanger gives the feeling that it is three-dimensional while being completely flat, saving space and convenient for storage and hanging. Available in two models, 6 cubes including 11 openings used for storage and three cubes including 5 openings used for hanging. This product is 6 cubes. This is a decorative and designed gift that is very useful for the home, helps with organization and order and is pleasing to the eye. Dimensions: height 24cm, width 22.7cm thickness&nbsp;2&nbsp;mm. Color: black. Weight: 300&nbsp;grams. Material: iron with oven painting.</p><p class="ql-align-right"><br></p><p>Sold in high-quality cellophane packaging, flat and space-saving.</p>','AD122',69.00,NULL,ARRAY['assets/product-1773749725656-p6v2av.webp','assets/product-1773749726267-6hict.webp','assets/product-1773749726838-91hp2.webp']::text[],'in_stock',true,0),
('6432697e-68fc-4295-ada2-fee5e745c82c','f646f62d-2bf6-4721-9020-141031e08ece','קולב קוביות תלת מימד - 3 קוביות','3D Cubes Hanger - 3 Cubes','kvlb-kvbyvt-tlt-mymd-3-kvbyvt-ag7n7k','<p class="ql-align-right">מתלה בצורת קוביות תלת מימדיות המשמש לאחסון מטפחות, עניבות, צעיפים, חגורות, תכשיטים ועוד. המתלה נותן תחושה שהוא תלת מימדי בעוד הוא שטוח לגמרי, חוסך מקום ונוח לאחסון ותליה. קיים בשני דגמים, 6 קוביות הכולל 11 פתחים המשמשים לאחסון ושלוש קוביות הכולל 5 פתחים המשמשים לתליה. מוצר זה הוא 3&nbsp;קוביות. זו מתנה דקורטיבית ומעוצבת ומאוד שימושית לבית, עוזרת בארגון וסדר ויפה לעין. מידות: גובה 24ס"מ, רוחב 22.7ס"מ עובי&nbsp;2&nbsp;מ"מ. צבע: שחור. משקל: 300&nbsp;גרם. חומר: ברזל בצביעה בתנור.</p><p class="ql-align-right"><br></p><p>נמכר באריזת צלופן איכותית, שטוחה וחוסכת מקום.</p>','<p class="ql-align-right">A hanger in the shape of three-dimensional cubes used for storing handkerchiefs, ties, scarves, belts, jewelry and more. The hanger gives the impression of being three-dimensional while being completely flat, saving space and convenient for storage and hanging. Available in two models: 6 cubes including 11 openings for storage and three cubes including 5 openings for hanging. This product is 3&nbsp;cubes. This is a decorative and stylish gift that is very useful for the home, helps with organization and order and is pleasing to the eye. Dimensions: height 24cm, width 22.7cm thickness&nbsp;2&nbsp;mm. Color: black. Weight: 300&nbsp;grams. Material: iron with oven painting.</p><p class="ql-align-right"><br></p><p>Sold in high-quality cellophane packaging, flat and space-saving.</p>','AD123',69.00,NULL,ARRAY['assets/product-1773749724460-luq9l.webp']::text[],'in_stock',true,0),
('558588f0-963c-478c-b9c5-50b15ad1f321','f646f62d-2bf6-4721-9020-141031e08ece','תלוי - אלברט - מתלה מבוסס שיווי משקל','Hanging - Albert - Balance-Based Hanger','tlvy-albrt-mtlh-mbvss-shyvvy-mshkl-1bm4rh','<p class="ql-align-right">מתלה למדף ולשולחן בצורת קוף. המתלה יכול להיות תלוי על המדף גם מבלי שהוא מחזיק דבר. המתלה יכול לשמש לתליה של אביזרים שונים, גדולים וקטנים, קלים וגם כבדים מאוד. לתליה של חפצים שונים כגון עציץ, תיק, מעיל, מטריה, מפתחות או אפילו אשכול בננות או ענבים, סל קניות וכו'' וכו''... תוספת אלגנטית לאחסון ולקישוט המדפים. מתאים לחפצים במשקל שאינו עולה על 5 ק"ג.</p>','<p class="ql-align-right">A monkey-shaped hanger for shelves and tables. The hanger can hang on the shelf even without holding anything. The hanger can be used to hang various accessories, large and small, light and even very heavy. For hanging various objects such as a planter, bag, coat, umbrella, keys or even a bunch of bananas or grapes, shopping basket, etc... An elegant addition for storage and decorating shelves. Suitable for objects weighing up to 5 kg.</p>','AD279',55.00,NULL,ARRAY['assets/product-1773749708752-tpeldhu.webp','assets/product-1773749709362-v75z.webp','assets/product-1773749709983-2akele.webp','assets/product-1773749712752-zasskv.webp']::text[],'in_stock',true,0),
('b5bdf420-f700-4c4f-b9c5-2448ea5b7e4f','2420ab78-5daa-4119-8e1d-b986d78ab658','פסלוני חתולים - סט של חמישה חתולים דקורטיביים להצבה על מדף','Cat Figurines - Set of Five Decorative Cats for Shelf Display','pslvny-chtvlym-st-shl-chmyshh-chtvlym-dkvrtybyym-lhtsbh-al-mdp-2gzpl3','<p>מחקרים מראים שצפייה בחתולים מפחיתה חרדה, מתח ולחץ ומסייעת להרגעת הנפש</p><p class="ql-align-right">סדרה של חמש צלליות של חתולים מקסימים שיושבים על קצה מדף. מיועד לקישוט מדפים, נישות, מעקים וכו׳.</p><p class="ql-align-right">משפחת החתולים כוללת את הדמויות הבולטות דיווה, צ''רצ''יל, אוסקר, שרלוק ופרינסס.</p><p>עשוי מתכת. צבע: שחור</p>','<p>Studies show that looking at cats reduces anxiety, tension and stress and helps calm the mind</p><p class="ql-align-right">A series of five silhouettes of adorable cats sitting on the edge of a shelf. Designed to decorate shelves, niches, railings, etc.</p><p class="ql-align-right">The cat family includes the prominent characters Diva, Churchill, Oscar, Sherlock and Princess.</p><p>Made of metal. Color: black</p>','AD192AB',220.00,NULL,ARRAY['assets/product-1774449316497-nm9r7j.webp','assets/product-1773749708952-6mo0c.webp','assets/product-1773749709730-jz31a.webp','assets/product-1773749710245-t0jcpm.webp','assets/product-1773749710702-74fo0f.webp','assets/product-1773749711077-2yd6k.webp','assets/product-1774449044392-oaro7.webp','assets/product-1774449049249-l82u29.webp','assets/product-1774449053553-gulqqs.webp','assets/product-1774449056955-06drx.webp','assets/product-1774449060577-yit26j.webp','assets/product-1774449063766-yuuijb.webp']::text[],'in_stock',true,0),
('6f701f81-1325-4039-ae9f-849af83c5162','f646f62d-2bf6-4721-9020-141031e08ece','אולה - מתלה מעוצב למגבת מטבח או למגבת ידיים','Ola - Decorative Kitchen Towel or Hand Towel Holder','avlh-mtlh-mavtsb-lmgbt-mtbch-av-lmgbt-ydyym-xwn0ms','<p class="ql-align-right">מתלה בצורת רקדנית פלמנקו. בכל פעם שאתם מחליפים מגבת, היא מחליפה שמלה. ניתן לתלות על הקיר, על ארון המטבח או על כל משטח חלק באמצעות דבק דו צדדי איכותי של חברת 3M (כלול) או על הקיר באמצעות בורג (לא מסופק). מתנה אידיאלית ושימושית למטבח. צבע: שחור. מידות: גובה 24 ס&quot;מ, רוחב 1.5 ס&quot;מ אורך 12.5 ס&quot;מ. משקל כולל אריזה: 135 גרם. חומר: ברזל בצביעה בתנור.</p>','<p class="ql-align-right">A towel holder in the shape of a flamenco dancer. Every time you change the towel, she changes her dress. Can be hung on the wall, on a kitchen cabinet, or on any smooth surface using high-quality 3M double-sided adhesive tape (included), or on the wall using a screw (not supplied). An ideal and practical kitchen gift. Color: Black. Dimensions: Height 24 cm, Width 1.5 cm, Length 12.5 cm. Weight including packaging: 135 grams. Material: Powder-coated iron.</p>','AD261',55.00,NULL,ARRAY['assets/product-1787510059627-b2s7ar.webp','assets/product-1787510080286-sggxur.webp','assets/product-1787510030669-g7ok05.webp','assets/product-1787510104605-riqfwa.webp','assets/product-1787510012455-pz2ikm.webp','assets/product-1773749708157-wbfoqq.webp','assets/product-1773749708830-he5alh.webp','assets/product-1773749709298-9c265q.webp','assets/product-1773749709690-24ydp.webp','assets/product-1773749710349-wf3hxy.webp','assets/product-1787510181140-2vb9f.webp','assets/product-1787510188903-dafmvj.webp']::text[],'in_stock',true,0),
